import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from env import *
exec(open(HERE/'helpers_a.py').read().split("async def main")[0])
async def login(pg):
    await pg.evaluate("(()=>{toggleAdminLoginModal(true);return 1})()")
    await pg.fill('#admin-password-input','Bacha2026!'); await pg.evaluate("(()=>{handleAdminLogin();return 1})()"); await pg.wait_for_timeout(1800)
async def main():
    reset_db()
    sh("update admin_settings set pin_hash=extensions.crypt('Bacha2026!', extensions.gen_salt('bf')), pin_changed=true",role=None)
    sh("insert into store_settings values('store_mode','open') on conflict (key) do update set value='open'",role=None)
    async with async_playwright() as p:
        b=await p.chromium.launch(); pg,errs=await newpage(b,1024,768)
        await login(pg)
        await pg.evaluate("(()=>{switchAdminTab('customize');return 1})()"); await pg.wait_for_timeout(400)
        await pg.fill('#new-cat-icon','🍞'); await pg.fill('#new-cat-name','Bread'); await pg.evaluate("(()=>{addCategory();return 1})()"); await pg.wait_for_timeout(1500)
        r,_=sh("select value from store_settings where key='site_options'",role=None); ok('category saved to database','Bread' in r,r[:80])
        ok('new category in add-item and item cards',await pg.evaluate("document.querySelector('#add-prod-cat').innerHTML.includes('Bread')&&document.querySelector('#customization-cards-grid').innerHTML.includes('Bread')"))
        await pg.evaluate("(()=>{switchAdminTab('deadline');return 1})()"); await pg.wait_for_timeout(500)
        await pg.evaluate("(()=>{togglePayOption('gcash');return 1})()"); await pg.wait_for_timeout(1500)
        r,_=sh("select value::jsonb->'payments' from store_settings where key='site_options'",role=None); ok('GCash toggle saved',r=='{"cod": true, "gcash": false}',r)
        await pg.evaluate("(()=>{togglePayOption('cod');return 1})()"); await pg.wait_for_timeout(600); await modal_ok(pg)
        r,_=sh("select value::jsonb->'payments'->>'cod' from store_settings where key='site_options'",role=None); ok('cannot turn both off',r=='true',r)
        await pg.evaluate("(()=>{togglePayOption('gcash');return 1})()"); await pg.wait_for_timeout(1200)
        await pg.evaluate("""(()=>{document.getElementById('dl-enabled').checked=true;syncDeliveryForm();document.getElementById('dl-km').value='5';document.getElementById('dl-lat').value='14.5995';document.getElementById('dl-lng').value='120.9842';saveDeliveryOptions();return 1})()"""); await pg.wait_for_timeout(1500); await modal_ok(pg)
        r,_=sh("select value::jsonb->'delivery'->>'maxKm' from store_settings where key='site_options'",role=None); ok('delivery limit saved',r=='5',r)
        await pg.evaluate("""(()=>{draftSocials.push({platform:'Instagram',url:'https://instagram.com/bacha'});renderSiteCard();saveSocials();return 1})()"""); await pg.wait_for_timeout(1500); await modal_ok(pg)
        r,_=sh("select value::jsonb->'socials'->0->>'url' from store_settings where key='site_options'",role=None); ok('social link saved',r=='https://instagram.com/bacha',r)
        await pg.screenshot(path=shot('p8a_admin.png'),full_page=True)
        ok('no page errors (admin)',not errs,str(errs[:2]))
        # customer side
        ctx=await b.new_context(viewport={'width':390,'height':844},permissions=['geolocation'],geolocation={'latitude':14.80,'longitude':121.2},timezone_id='Asia/Manila')
        await ctx.expose_function('__py',py); c=await ctx.new_page(); cerr=[]; c.on('pageerror',lambda e:cerr.append(str(e)))
        await c.add_init_script(RD); await c.goto(URL); await c.wait_for_timeout(1500)
        ok('customer sees payment/delivery options',await c.evaluate("siteOpts.payments.gcash===true&&siteOpts.delivery.limitEnabled===true"))
        ok('single cookies hidden from customer menu',await c.evaluate("!document.getElementById('single-filter-pills').innerHTML.includes('Cookies')&&!document.getElementById('single-menu-grid').innerHTML.includes('addSingleToCart(1)')"))
        await c.evaluate("(()=>{toggleCartDrawer(true);setFulfillment('delivery');checkDeliveryLocation();return 1})()"); await c.wait_for_timeout(1500)
        ok('far customer is moved to pick-up',await c.evaluate("fulfillment==='pickup'&&deliveryCheck.tooFar===true&&document.getElementById('ful-delivery').disabled"))
        await c.screenshot(path=shot('p8a_far.png'))
        await c.context.set_geolocation({'latitude':14.60,'longitude':120.99}); await c.evaluate("(()=>{deliveryCheck.tooFar=false;setFulfillment('delivery');checkDeliveryLocation();return 1})()"); await c.wait_for_timeout(1500)
        print(await c.evaluate("JSON.stringify([fulfillment,deliveryCheck,document.getElementById('cust-maps').value,document.getElementById('delivery-km-note').textContent])"))
        ok('near customer can deliver and maps link is filled',await c.evaluate("fulfillment==='delivery'&&document.getElementById('cust-maps').value.startsWith('https://www.google.com/maps')"))
        await c.screenshot(path=shot('p8a_near.png'))
        # GCash off -> pickup pays cash
        sh("update store_settings set value=jsonb_set(value::jsonb,'{payments}','{\"gcash\":false,\"cod\":true}')::text where key='site_options'",role=None)
        await c.evaluate("(()=>{loadDisplayMode();return 1})()"); await c.wait_for_timeout(1500); await c.evaluate("(()=>{setFulfillment('pickup');return 1})()")
        ok('GCash off: pick-up is cash and receipt box hidden',await c.evaluate("payMethod==='COD'&&document.getElementById('gcash-section').classList.contains('hidden')&&!document.getElementById('cash-pickup-info').classList.contains('hidden')"))
        # closed screen shows socials
        sh("update store_settings set value='batch_closed' where key='store_mode'",role=None)
        await c.evaluate("(()=>{loadDisplayMode();return 1})()"); await c.wait_for_timeout(1500)
        ok('closed screen shows the social link',await c.evaluate("document.getElementById('closed-socials').innerHTML.includes('instagram.com/bacha')"))
        ok('no page errors (customer)',not cerr,str(cerr[:2]))
        await b.close()
    print('RESULT',sum(res),'/',len(res)); sys.exit(0 if all(res) else 1)
asyncio.run(main())
